package io.knowledgebrain.notification;
import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_NOTIFICATION_DATABASE_URL",matches=".+")
class ReviewLifecycleStoreIntegrationTest {
 GroupReviewStoreIntegrationTest f;byte[] source;long after;
 @BeforeEach void setup(){f=new GroupReviewStoreIntegrationTest();f.setup();after=f.sql.queryForObject("SELECT max(enabled_after) FROM group_review_source_activation",Long.class);f.store=new GroupReviewStore(f.ds,Clock.fixed(Instant.ofEpochMilli(after-1000),ZoneOffset.UTC));source=ReviewFixtures.feedback(f.a,after+100);}
 @AfterEach void clean(){f.clean();}
 byte[] bytes(boolean grade,String state,long version,UUID id,long at)throws Exception{return ReviewLifecycleFixtures.event(source,grade,state,version,id,at);}
 @Test void retractionRestorationAndReplayKeepFourIndependentFactsAndReadState()throws Exception{f.enable();var original=new ArrayList<byte[]>();for(boolean grade:List.of(false,true)){var id=ReviewFixtures.ids.next();for(int n=1;n<=2;n++){var b=bytes(grade,n==1?"RETRACTED":"RESTORED",n,id,after+100+n);original.add(b);assertTrue(f.store.accept(ReviewSignal.decode(ReviewSignal.TOPICS.get(grade?4:3),b)));}}var rows=f.store.list(f.a,"ACTIVE","ALL",null,20).items();assertEquals(4,rows.size());assertEquals(Set.of("FEEDBACK_RETRACTED","FEEDBACK_RESTORED","GRADE_RETRACTED","GRADE_RESTORED"),new HashSet<>(rows.stream().map(GroupReviewStore.Notice::kind).toList()));var n=rows.getFirst();f.store.change(f.a,n.notificationId(),1,true,false,ReviewFixtures.trace);for(var b:original){boolean grade=io.knowledgebrain.contracts.collaboration.feedbackretraction.v1.FeedbackRetractionEnvelopeV1.parseFrom(b).getAggregateType().equals("GradeRetraction");assertFalse(new GroupReviewStore(f.ds,Clock.systemUTC()).accept(ReviewSignal.decode(ReviewSignal.TOPICS.get(grade?4:3),b)));}assertTrue(f.store.get(f.a,n.notificationId()).read());assertEquals(4,f.count("group_review_receipt"));}
 @Test void newlySupportedHistoryIsSuppressedEvenForExistingConsentAndCutoffSurvivesRestart()throws Exception{f.enable();var id=ReviewFixtures.ids.next();var old=ReviewSignal.decode(ReviewSignal.TOPICS.get(3),bytes(false,"RETRACTED",1,id,after-1));assertFalse(f.store.accept(old));assertEquals("BEFORE_SOURCE_ACTIVATION",f.sql.queryForObject("SELECT decision FROM group_review_receipt WHERE event_id=?",String.class,old.eventId()));assertFalse(new GroupReviewStore(f.ds,Clock.systemUTC()).accept(old));assertTrue(f.store.accept(ReviewSignal.decode(ReviewSignal.TOPICS.get(3),bytes(false,"RESTORED",2,id,after+1))));assertEquals(2,f.sql.queryForObject("SELECT count(*) FROM group_review_source_activation",Integer.class));assertEquals(after,f.sql.queryForObject("SELECT max(enabled_after) FROM group_review_source_activation",Long.class));assertTrue(f.store.accept(ReviewFixtures.signal(f.a,after-1)));}
 @Test void defaultOffDisabledIntervalAndBeforeConsentStayDurable()throws Exception{var old=ReviewSignal.decode(ReviewSignal.TOPICS.get(4),bytes(true,"RETRACTED",1,ReviewFixtures.ids.next(),after+100));assertFalse(f.store.accept(old));f.enable();assertFalse(f.store.accept(old));f.store.preference(f.a,1,false,ReviewFixtures.trace);var disabled=ReviewSignal.decode(ReviewSignal.TOPICS.get(3),bytes(false,"RETRACTED",1,ReviewFixtures.ids.next(),after+100));assertFalse(f.store.accept(disabled));f.store.preference(f.a,2,true,ReviewFixtures.trace);assertFalse(f.store.accept(disabled));var before=ReviewSignal.decode(ReviewSignal.TOPICS.get(3),bytes(false,"RETRACTED",1,ReviewFixtures.ids.next(),after+100));var later=new GroupReviewStore(f.ds,Clock.fixed(Instant.ofEpochMilli(after+200),ZoneOffset.UTC));later.preference(f.a,3,false,ReviewFixtures.trace);later.preference(f.a,4,true,ReviewFixtures.trace);assertFalse(later.accept(before));assertEquals(0,f.count("group_review_notification"));}
 @Test void missingActivationAndOutboxFailureNeverAcknowledgeOrPartiallyCreate()throws Exception{f.enable();var v=ReviewSignal.decode(ReviewSignal.TOPICS.get(3),bytes(false,"RETRACTED",1,ReviewFixtures.ids.next(),after+100));f.sql.update("DELETE FROM group_review_source_activation WHERE source='feedback-retraction'");assertThrows(RuntimeException.class,()->f.store.accept(v));assertEquals(0,f.count("group_review_receipt"));f.sql.update("INSERT INTO group_review_source_activation VALUES ('feedback-retraction',?)",after);f.sql.execute("CREATE FUNCTION fail_lifecycle() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'controlled'; END $$");f.sql.execute("CREATE TRIGGER fail_lifecycle BEFORE INSERT ON outbox_event FOR EACH ROW EXECUTE FUNCTION fail_lifecycle()");assertThrows(RuntimeException.class,()->f.store.accept(v));assertEquals(0,f.count("group_review_receipt"));assertEquals(0,f.count("group_review_notification"));assertEquals(0,f.count("group_review_revision"));}
}
